(6742339, 1008906, 46918, '<td valign="top">I love the feel of the old schoolhouse.</td>', 'I love the feel of the old schoolhouse.', '2012-04-15 17:38:30.000000', NULL, 1),
(6742341, 1008962, 10785, '<td valign="top">I think you went a little heavy on the HDR and the sharpening here. Also the white vignetter really stands out a bit too much. You did do a good job of making the subject stand out from such a busy background.</td>', 'I think you went a little heavy on the HDR and the sharpening here. Also the white vignetter really stands out a bit too much. You did do a good job of making the subject stand out from such a busy background.', '2012-04-15 17:42:39.000000', NULL, 1),
(6742342, 1009415, 10785, '<td valign="top">I really like this shot. It has a photo impressionism quality to it. Unfortunately this was the grunge challenge. I just don''t think the subject of the photo or the processing came off as grungy.</td>', 'I really like this shot. It has a photo impressionism quality to it. Unfortunately this was the grunge challenge. I just don''t think the subject of the photo or the processing came off as grungy.', '2012-04-15 17:44:21.000000', NULL, 1),
