INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6742385, 1008658, 86447, '<td valign="top">This is very interesting.  I think the over-saturation detracts and makes it hard to find the subject, but it''s interesting.<br/> <br/>(commenting only)</td>', 'This is very interesting.  I think the over-saturation detracts and makes it hard to find the subject, but it''s interesting. (commenting only)', '2012-04-15 18:38:48.000000', NULL, 1),
(6742387, 1009636, 86447, '<td valign="top">I totally LOVE this chicken!   Since it''s Expert editing, I wish you''d gotten rid of the green stuff and maybe just put nothing in there, or more of the dirt.   As it is, the green stuff is so busy, that it makes it difficult to find the subject at first.<br/> <br/>I LOVE that chicken!  Look at his stance!   Love!<br/> <br/> <br/>(commenting only)</td>', 'I totally LOVE this chicken!   Since it''s Expert editing, I wish you''d gotten rid of the green stuff and maybe just put nothing in there, or more of the dirt.   As it is, the green stuff is so busy, that it makes it difficult to find the subject at first. I LOVE that chicken!  Look at his stance!   Love!  (commenting only)', '2012-04-15 18:40:30.000000', NULL, 1),
(6742388, 1009375, 86447, '<td valign="top">I don''t know how to judge this challenge topic...  but I think this is very well done.<br/> <br/>(commenting only)</td>', 'I don''t know how to judge this challenge topic...  but I think this is very well done. (commenting only)', '2012-04-15 18:40:50.000000', NULL, 1),
(6742391, 1009616, 86447, '<td valign="top">I don''t know how to judge this challenge topic...  but I like this image.  I wish, though, that the rear legs of the chair had a shadow to keep it from "floating in mid air" in my mind.<br/> <br/>(commenting only)</td>', 'I don''t know how to judge this challenge topic...  but I like this image.  I wish, though, that the rear legs of the chair had a shadow to keep it from "floating in mid air" in my mind. (commenting only)', '2012-04-15 18:41:52.000000', NULL, 1),
(6742392, 1009594, 86447, '<td valign="top">Wow.  Interesting.   WHAT is this!?<br/> <br/> <br/>(commenting only)</td>', 'Wow.  Interesting.   WHAT is this!?  (commenting only)', '2012-04-15 18:42:13.000000', NULL, 1),
(6742394, 1009550, 86447, '<td valign="top">Ha!   Great sign!  LOL!<br/> <br/>The oversaturation almost makes my eyes hurt, though.  <br/> <br/>(commenting only)</td>', 'Ha!   Great sign!  LOL! The oversaturation almost makes my eyes hurt, though.   (commenting only)', '2012-04-15 18:43:18.000000', NULL, 1),
